  lv_draw_buf_t db;
  lv_obj_t *scr;
  const uint8_t *src;
  uint32_t stride;
  int x0 = g_cap_win_x;
  int y0 = g_cap_win_y;
  int w = g_cap_win_w;
  int h = g_cap_win_h;
  int hstep;
  int vstep;
  int cols;
  int rows;
  int rx;
  int ry;

  scr = lv_screen_active();
  if (scr == NULL || g_cap_buf == NULL ||
      g_cap_bufsize < 480 * 320 * 2u + 64u)
    {
      printf("[CapaA] 参数错误\n");
      fflush(stdout);
      return -1;
    }

  if (x0 < 0)
    {
      x0 = 0;
    }

  if (y0 < 0)
    {
      y0 = 0;
    }

  if (x0 + w > 480)
    {
      w = 480 - x0;
    }

  if (y0 + h > 320)
    {
      h = 320 - y0;
    }

  if (w <= 0 || h <= 0)
    {
      x0 = 0;
      y0 = 0;
      w = 480;
      h = 320;
    }

